-- Stored values safe where they show (docs/DECISIONS.md): values saved before every door checked their shape go back into it.
-- A glass tint that isn't #rrggbb goes back to none, and the rest are lowercase, as the API keeps them.
UPDATE games SET glass_tint_color = NULL WHERE glass_tint_color IS NOT NULL AND (length(glass_tint_color) != 7 OR lower(glass_tint_color) NOT GLOB '#[0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f][0-9a-f]');
UPDATE games SET glass_tint_color = lower(glass_tint_color) WHERE glass_tint_color IS NOT NULL;
-- Shown text loses the soft hyphen, zero-width space, word joiner, byte order mark and the direction embeddings, overrides and isolates (173, 8203, 8234, 8235, 8236, 8237, 8238, 8288, 8294, 8295, 8296, 8297, 65279),
-- the ones text pasted from elsewhere carries (HIDDEN_CHARACTERS, packages/core/src/shown-text.ts). Only rows that hold one are rewritten.
UPDATE games SET title = replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(title, char(173), ''), char(8203), ''), char(8234), ''), char(8235), ''), char(8236), ''), char(8237), ''), char(8238), ''), char(8288), ''), char(8294), ''), char(8295), ''), char(8296), ''), char(8297), ''), char(65279), '')
  WHERE title GLOB '*[' || char(173, 8203, 8234, 8235, 8236, 8237, 8238, 8288, 8294, 8295, 8296, 8297, 65279) || ']*';
